.app-header {
  min-height: 62px; display: grid; grid-template-columns: 42px 1fr auto; gap: 10px;
  align-items: center; padding: 8px 14px; background: var(--primary); color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}
.app-menu-button { width:40px;height:40px;display:grid;place-content:center;gap:4px;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer; }
.app-menu-button span { width:20px;height:2px;border-radius:9px;background:currentColor; }
.app-brand { min-width:0;display:flex;align-items:center;gap:8px;font-size:16px;letter-spacing:-.02em; }
.app-brand img { width:27px;height:27px;object-fit:contain;filter:brightness(0) invert(1); }
.app-role { font-size:10px;font-weight:800;opacity:.8;text-transform:uppercase;letter-spacing:.06em; }
.app-notification-button{position:relative;width:40px;height:40px;display:grid;place-items:center;padding:0;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer}.app-notification-button:hover{background:rgba(255,255,255,.09)}.app-notification-button svg{width:22px;height:22px}.app-notification-badge{position:absolute;right:2px;top:2px;min-width:17px;height:17px;display:grid;place-items:center;padding:0 4px;border:2px solid var(--primary);border-radius:999px;background:#d92d20;color:#fff;font-size:9px;font-weight:900;line-height:1}

.client-home-head{margin-bottom:6px}.client-home-head h1{margin:0 0 8px;color:var(--primary);font-size:24px;line-height:1.15}.client-home-head p{margin:0;color:var(--muted);font-size:14px;line-height:1.5}

.professional-search{padding:16px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:0 4px 12px rgba(15,23,42,.035)}.search-heading h2{margin:0 0 5px;color:var(--primary);font-size:16px}.search-heading p{margin:0;color:var(--muted);font-size:12px;line-height:1.45}.search-group{margin-top:14px}.search-label{display:block;margin-bottom:7px;color:var(--text);font-size:12px;font-weight:800}.type-options{display:flex;gap:7px;flex-wrap:wrap}.type-option{min-height:34px;padding:7px 10px;border:1px solid var(--line);border-radius:999px;background:#f8fafc;color:var(--text);font-size:11px;font-weight:800;cursor:pointer}.type-option.is-active{border-color:#a9c6ee;background:#e7f0ff;color:var(--primary)}.filter-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(120px,.65fr);gap:10px;margin-top:14px}.filter-field{display:grid;gap:6px;align-content:start}.filter-field>span{font-size:11px;font-weight:800;color:var(--muted)}.filter-field select{width:100%;min-height:40px;padding:8px 10px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--text);font-size:12px}.area-add-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px}.area-add{min-height:40px;padding:8px 11px;border:1px solid #a9c6ee;border-radius:10px;background:#e7f0ff;color:var(--primary);font-size:11px;font-weight:900;cursor:pointer}.selected-areas{display:flex;gap:6px;flex-wrap:wrap;min-height:29px;align-items:center}.selected-area-empty,.selected-area-chip{display:inline-flex;align-items:center;gap:5px;min-height:27px;padding:5px 8px;border:1px solid #c9dcf5;border-radius:999px;background:#edf4ff;color:var(--primary);font-size:10px;font-weight:800}.selected-area-chip button{display:grid;width:17px;height:17px;place-items:center;padding:0;border:0;border-radius:50%;background:rgba(16,35,63,.1);color:var(--primary);font-size:12px;line-height:1;cursor:pointer}.filter-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.filter-apply,.filter-clear{min-height:39px;padding:9px 13px;border-radius:10px;font-size:12px;font-weight:800;cursor:pointer}.filter-apply{border:1px solid var(--primary);background:var(--primary);color:#fff}.filter-clear{border:1px solid var(--line);background:#fff;color:var(--primary)}@media(max-width:460px){.filter-grid{grid-template-columns:1fr}.filter-actions button{flex:1 1 130px}.area-add-row{grid-template-columns:minmax(0,1fr) auto}}

.professional-results{display:grid;gap:12px}.results-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.results-head h2{margin:0 0 4px;color:var(--primary);font-size:17px}.results-head p{margin:0;color:var(--muted);font-size:12px}.result-count{display:grid;min-width:34px;height:28px;place-items:center;padding:0 8px;border-radius:999px;background:#e7f0ff;color:var(--primary);font-size:11px;font-weight:900}.professional-map{position:relative;height:250px;overflow:hidden;border:1px solid #bed3ee;border-radius:14px;background:linear-gradient(145deg,#dceaff,#edf5ff 48%,#d9e8f7)}.professional-map:before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.46) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.46) 1px,transparent 1px);background-size:38px 38px}.map-road{position:absolute;display:block;height:13px;border-radius:999px;background:rgba(255,255,255,.88);box-shadow:0 0 0 1px rgba(148,163,184,.12)}.road-a{width:82%;left:4%;top:43%;transform:rotate(-9deg)}.road-b{width:68%;left:26%;top:62%;transform:rotate(21deg)}.road-c{width:54%;left:35%;top:38%;transform:rotate(68deg)}.map-center{position:absolute;z-index:2;left:50%;top:50%;width:16px;height:16px;border:4px solid #fff;border-radius:50%;background:#2563eb;box-shadow:0 0 0 4px rgba(37,99,235,.18)}.map-marker{position:absolute;z-index:3;width:31px;height:31px;display:grid;place-items:center;transform:translate(-50%,-50%);border:2px solid #fff;border-radius:50% 50% 50% 8px;background:var(--primary);color:#fff;box-shadow:0 5px 12px rgba(16,35,63,.22);font-size:9px;font-weight:900;cursor:pointer}.map-marker span{transform:rotate(0)}.active-filters{display:flex;gap:7px;flex-wrap:wrap}.active-filters span{padding:5px 9px;border:1px solid #c9dcf5;border-radius:999px;background:#edf4ff;color:var(--primary);font-size:10px;font-weight:800}.result-order{display:grid;grid-template-columns:34px 1fr;gap:10px;align-items:center;padding:11px;border:1px solid #bed3ee;border-radius:12px;background:#f4f8ff}.order-icon{display:grid;width:34px;height:34px;place-items:center;border-radius:10px;background:var(--primary);color:#fff;font-size:9px;font-weight:900}.result-order strong,.result-order small{display:block}.result-order strong{font-size:11px}.result-order small{margin-top:2px;color:var(--muted);font-size:10px;line-height:1.35}.professional-list{display:grid;gap:9px}.professional-item{width:100%;min-height:66px;display:grid;grid-template-columns:40px minmax(0,1fr) auto 12px;gap:9px;align-items:center;padding:10px 11px;border:1px solid var(--line);border-radius:13px;background:#fff;color:var(--text);text-align:left;box-shadow:0 4px 11px rgba(15,23,42,.035);cursor:pointer}.professional-avatar{display:grid;width:40px;height:40px;place-items:center;border-radius:11px;background:#e7f0ff;color:var(--primary);font-size:11px;font-weight:900}.professional-copy{min-width:0}.professional-copy strong,.professional-copy small{display:block}.professional-copy strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.professional-copy small{margin-top:4px;color:var(--muted);font-size:9px;line-height:1.35}.professional-status{padding:4px 6px;border-radius:999px;font-size:8px;font-weight:900}.status-online{background:#ecfdf3;color:#039855}.status-offline{background:#f2f4f7;color:#667085}.professional-chevron{color:var(--muted);font-size:20px}.results-empty{padding:18px;border:1px dashed #b8c5d6;border-radius:13px;background:#f8fafc;text-align:center}.results-empty strong,.results-empty span{display:block}.results-empty strong{font-size:12px}.results-empty span{margin-top:4px;color:var(--muted);font-size:10px}@media(min-width:720px){.professional-map{height:320px}.professional-item{grid-template-columns:44px minmax(0,1fr) auto 16px;padding:12px 14px}.professional-avatar{width:44px;height:44px}.professional-copy strong{font-size:13px}.professional-copy small{font-size:10px}}

.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

.prototype-drawer.open { display: block; }

.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

.drawer-profile { min-width: 0; }
.drawer-profile strong,
.drawer-profile small { display: block; }
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online-copy strong,
.drawer-online-copy small { display: block; }
.drawer-online-copy strong { font-size: 13px; }
.drawer-online-copy small { margin-top: 2px; color: #bfdbfe; font-size: 10px; }
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}
.drawer-online.is-offline .online-dot { background: #98a2b3; box-shadow: none; }
.online-switch { position: relative; width: 38px; height: 22px; border-radius: 999px; background: #22c55e; }
.online-switch b { position: absolute; top: 3px; right: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 19px; }

.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}
.drawer-nav::-webkit-scrollbar { width: 5px; }
.drawer-nav::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(255, 255, 255, .35); }

.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-nav button:hover { background: rgba(255, 255, 255, .08); }
.drawer-icon { flex: 0 0 20px; width: 20px; height: 20px; color: #aebee5; }

.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}
.drawer-footer-top { display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}
.drawer-logout svg { width: 18px; height: 18px; color: #aebee5; }
.drawer-footer small { color: #aebee5; font-size: 10px; }
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.drawer-emergency:hover { background: rgba(255, 255, 255, .08); }

@media (max-width: 420px) {
  .drawer-panel { width: 80vw; }
  .drawer-top { padding-top: 24px; }
}
